// Builds the per-part review bundle for the NKSkills pilot.
// Reads collected snapshots as inert text only; never executes target content and performs no network access.
// Usage: node build-part-review.mjs CAMPAIGN_DIR INDEX_DIR DISCOVERY_DIR OUT_BUNDLE.json
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";

const [campaignDir, indexDir, discoveryDir, outFile] = process.argv.slice(2);
const PART = "parts/000001";
const partDir = path.join(campaignDir, PART);
const sha = (s) => createHash("sha256").update(s).digest("hex");
const L = (f) => fs.readFileSync(f, "utf8").trim().split("\n").map(JSON.parse);
const inv = L(path.join(partDir, "inventory.jsonl"));
const ev = L(path.join(partDir, "evidence.jsonl"));
const index = JSON.parse(fs.readFileSync(path.join(indexDir, "index.json"), "utf8"));
const graph = L(path.join(discoveryDir, "graph.jsonl"));
const graphHash = sha(fs.readFileSync(path.join(discoveryDir, "graph.jsonl")));
const discovery = JSON.parse(fs.readFileSync(path.join(discoveryDir, "discovery.json"), "utf8"));
const now = new Date().toISOString();
const REVIEWER =
  "Claude (model claude-fable-5-2), host reviewer running the content-search-audit skill; automated agent review, not a human domain expert";
const ORIGIN = "https://nkskills.getgroove.me";
const OWNER_CONTEXT =
  "Business context: NKSkills composes versioned skill workflows for Codex and Claude Code; English and Vietnamese audiences. AIO means AI search optimization; no Google AI Overviews measurements are supplied.";
const OWNER_SCOPE =
  "The sole authorized public origin is https://nkskills.getgroove.me. No credentials, authenticated providers or analytics exports are supplied.";

const s8 = (id) => id.slice(0, 8);
const byUri = new Map(inv.map((i) => [i.uri, i]));
const E = (item, kind) => ev.find((e) => e.itemId === item.itemId && e.kind === kind);
const P = inv.map((item) => {
  const content = E(item, "content");
  const http = E(item, "http-response");
  const policy = ev.filter((e) => e.itemId === item.itemId && e.kind === "crawler-policy");
  const html = content.value;
  const finalUrl = http.value.finalUrl ?? item.uri;
  const isHtml = /text\/html/.test(http.value.headers["content-type"] ?? "");
  const p = new URL(item.uri).pathname;
  const cls =
    p === "/" ? "home-redirect-alias" : /^\/(en|vi)\/$/.test(p) ? "home" : /catalog/.test(p) ? "catalog" : /solutions/.test(p) ? "solution" : /guides/.test(p) ? "guide" : "license-notice";
  return { item, content, http, policy, html, finalUrl, isHtml, cls, path: p };
});
const pageOf = (uri) => P.find((p) => p.item.uri === uri);

const decode = (s) =>
  s.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;|&#x27;/g, "'").replace(/&nbsp;/g, " ");
function extractText(p) {
  if (!p.isHtml) return p.html;
  let b = p.html.replace(/<script[\s\S]*?<\/script>/gi, "\n").replace(/<style[\s\S]*?<\/style>/gi, "\n");
  b = b.replace(/<\/(p|div|li|section|tr|h[1-6]|header|footer|nav|main|article|ul|ol|table|pre|details|summary|title|textarea|template|button|a)>/gi, "\n").replace(/<br\s*\/?>/gi, "\n");
  b = decode(b.replace(/<[^>]+>/g, " "));
  return b.split("\n").map((s) => s.replace(/[ \t\r]+/g, " ").trim()).filter(Boolean).join("\n") + "\n";
}
const attr = (tag, name) => (new RegExp(`\\s${name}="([^"]*)"`).exec(tag) || [])[1];
function head(p) {
  const h = p.html;
  const title = decode((/<title>([\s\S]*?)<\/title>/i.exec(h) || [])[1] ?? "");
  const meta = (n) => decode((new RegExp(`<meta (?:name|property)="${n}" content="([^"]*)"`).exec(h) || [])[1] ?? "");
  const alternates = {};
  for (const m of h.matchAll(/<link rel="alternate" hreflang="([^"]+)" href="([^"]+)">/g)) alternates[m[1]] = m[2];
  return {
    htmlLang: (/<html lang="([^"]+)"/.exec(h) || [])[1] ?? null,
    title,
    description: meta("description"),
    canonical: (/<link rel="canonical" href="([^"]+)">/.exec(h) || [])[1] ?? null,
    alternates,
    og: { type: meta("og:type"), title: meta("og:title"), description: meta("og:description"), image: meta("og:image"), url: meta("og:url") },
    metaRobots: (h.match(/<meta[^>]+name="(?:robots|googlebot)"[^>]*>/gi) || []),
    h1: (h.match(/<h1[\s\S]*?<\/h1>/gi) || []).map((s) => decode(s.replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim()),
    headings: [...h.matchAll(/<(h[2-3])[^>]*>([\s\S]*?)<\/\1>/gi)].map((m) => m[1] + ": " + decode(m[2].replace(/<[^>]+>/g, " ")).replace(/\s+/g, " ").trim()),
  };
}
for (const p of P) {
  p.head = p.isHtml ? head(p) : null;
  p.text = extractText(p);
  p.ids = new Set([...p.html.matchAll(/\sid="([^"]+)"/g)].map((m) => m[1]));
}

const records = [];
const artifacts = {};
const made = new Map(); // itemId -> {kind: evidenceId}
function add(p, kind, value, { method, locator, sources, limitations }) {
  const json = typeof value !== "string";
  const evidenceId = `rev1-${kind}-${s8(p.item.itemId)}`;
  const bytes = json ? JSON.stringify(value, null, 2) : value;
  const artifact = `evidence/${evidenceId}.${json ? "json" : "txt"}`;
  artifacts[artifact] = bytes;
  records.push({
    evidenceId, itemId: p.item.itemId, kind, value: json ? JSON.parse(bytes) : bytes, method, locator, collectedAt: now,
    snapshotHash: sha(bytes), artifact, encoding: json ? "json" : "utf8", sourceEvidenceIds: [...new Set(sources)],
    redaction: "No credentials or personal data; derived from public snapshot or task statement",
    limitations,
  });
  if (!made.has(p.item.itemId)) made.set(p.item.itemId, {});
  made.get(p.item.itemId)[kind] = evidenceId;
  return evidenceId;
}
const DER = "host-derived inert text analysis of collected snapshot (regex over source text; no DOM parser, no script execution, no network)";
const RAW_LIM = "Raw HTTP source only; rendered DOM, external stylesheets and scripts were not captured or executed";

// ---- cross-page helpers
const edgesFrom = (url) => graph.filter((g) => g.from === url);
const fragmentTargets = (p) => {
  const out = [];
  for (const m of p.html.matchAll(/<a\s[^>]*href="([^"]*#[^"]*)"/g)) {
    const u = new URL(m[1], p.finalUrl);
    const target = P.find((q) => q.finalUrl === u.origin + u.pathname && q.cls !== "home-redirect-alias") ?? null;
    const frag = decodeURIComponent(u.hash.slice(1));
    out.push({ href: m[1], resolved: u.href, fragment: frag, targetCollected: !!target, fragmentIdPresentInTargetSource: target ? target.ids.has(frag) : null });
  }
  const seen = new Set();
  return out.filter((o) => !seen.has(o.href) && seen.add(o.href));
};
const PROBES = {
  "codebase-onboarding 1.1.0": /1\.1\.0/,
  "problem-presentation 0.1.0": /0\.1\.0/,
  "status: technical release (EN 'technical release' / VI 'bản kỹ thuật|phát hành kỹ thuật')": /technical release|bản kỹ thuật|phát hành kỹ thuật/i,
  "status: evaluation candidate (EN 'evaluation candidate' / VI 'ứng viên đánh giá|đang đánh giá|ứng viên')": /evaluation candidate|ứng viên/i,
  "hosts: Codex": /Codex/,
  "hosts: Claude Code": /Claude Code/,
  "no direct-download archive (EN) / chưa có archive tải trực tiếp (VI)": /direct-download archive|direct archive download|archive (phát hành )?tải trực tiếp/i,
  "prerequisite: codegraph": /codegraph/,
  "prerequisite: rtk": /\brtk\b/,
  "three components (EN '3 components|three traceable components' / VI '3 thành phần|ba thành phần')": /3 components|three traceable components|3 thành phần|ba thành phần/i,
  "invocation token $codebase-onboarding-c4": /\$codebase-onboarding-c4/,
  "invocation token /codebase-onboarding-c4": /\/codebase-onboarding-c4/,
  "commercial gate 'remains open' (EN) / 'vẫn mở' (VI)": /gate remains open|vẫn mở/i,
  "commercial gate 'has not passed' (EN) / 'chưa qua cổng' (VI)": /not passed the commercial release gate|chưa qua cổng/i,
  "catalog count '15 Upstream Skills'": /15\s*(<[^>]+>\s*)*Upstream Skills/,
  "catalog count '02 Solution Skills'": /02\s*(<[^>]+>\s*)*Solution Skills/,
  "any explicit calendar date (YYYY-MM-DD or month-year) in visible text": /\b20\d\d-\d\d-\d\d\b|\b(January|February|March|April|May|June|July|August|September|October|November|December) 20\d\d\b|tháng \d{1,2}(,| năm)? 20\d\d/i,
